// Bridges OpenNext's `CloudflareEnv` global to the bindings generated by
// `wrangler types` into worker-configuration.d.ts (run `npm run cf-typegen`
// after changing wrangler.jsonc). Runtime secrets are set via
// `wrangler secret put`, so they aren't in wrangler.jsonc and must be
// declared here.

interface CloudflareEnv extends Cloudflare.Env {
  /** OAuth web client id for signing in with Google. */
  GOOGLE_OAUTH_CLIENT_ID: string;
  /** OAuth web client secret (server-side only). */
  GOOGLE_OAUTH_CLIENT_SECRET: string;
  /** Secret that signs the session cookie. Required: with none, signing in is refused. */
  SESSION_SECRET: string;
  /**
   * Public origin, e.g. https://broadsheet.apps.mrida.ng. Optional; derived
   * from the request when unset (local dev).
   */
  APP_URL?: string;
}
